--- a/ta4j-core/src/main/java/org/ta4j/core/indicators/helpers/RunningTotalIndicator.java
+++ b/ta4j-core/src/main/java/org/ta4j/core/indicators/helpers/RunningTotalIndicator.java
@@ -38,0 +39,4 @@ public class RunningTotalIndicator extends CachedIndicator<Num> {
+    private Num previousSum = zero();
+
+    // serial access detection
+    private int previousIndex = -1;
@@ -47,0 +52,16 @@ public class RunningTotalIndicator extends CachedIndicator<Num> {
+        // serial access can benefit from previous partial sums
+        // which saves a lot of CPU work for very long barCounts
+        if (previousIndex != -1 && previousIndex == index - 1) {
+            return fastPath(index);
+        }
+
+        return slowPath(index);
+    }
+
+    private Num fastPath(final int index) {
+        var newSum = partialSum(index);
+        updatePartialSum(index, newSum);
+        return newSum;
+    }
+
+    private Num slowPath(final int index) {
@@ -49 +69 @@ public class RunningTotalIndicator extends CachedIndicator<Num> {
-        for (int i = Math.max(getBarSeries().getBeginIndex(), index - barCount + 1); i <= index; i++) {
+        for (int i = Math.max(0, index - barCount + 1); i <= index; i++) {
@@ -51,0 +72,2 @@ public class RunningTotalIndicator extends CachedIndicator<Num> {
+
+        updatePartialSum(index, sum);
@@ -55,3 +77,13 @@ public class RunningTotalIndicator extends CachedIndicator<Num> {
-    @Override
-    public int getUnstableBars() {
-        return 0;
+    private void updatePartialSum(final int index, final Num sum) {
+        previousIndex = index;
+        previousSum = sum;
+    }
+
+    private Num partialSum(int index) {
+        var sum = this.previousSum.plus(indicator.getValue(index));
+
+        if (index >= barCount) {
+            return sum.minus(indicator.getValue(index - barCount));
+        }
+
+        return sum;
@@ -63,0 +96,5 @@ public class RunningTotalIndicator extends CachedIndicator<Num> {
+
+    @Override
+    public int getUnstableBars() {
+        return barCount;
+    }
